// ============================================
// VALIDATION INPUT - LLM Web Search
// RFC-014: Support context.* with fallback to root level
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- Provider configuration ---
const validProviders = ['openai', 'openai-mini', 'claude', 'claude-haiku', 'anthropic', 'gemini', 'gemini-pro', 'mistral', 'mistral-premium'];
const defaultModels = {
  openai: 'gpt-4o-search-preview',
  'openai-mini': 'gpt-4o-mini-search-preview',
  claude: 'claude-haiku-4-5-20251001',
  'claude-haiku': 'claude-haiku-4-5-20251001',
  anthropic: 'claude-haiku-4-5-20251001',
  gemini: 'gemini-2.5-flash',
  'gemini-pro': 'gemini-2.5-pro',
  mistral: 'mistral-medium-2505',
  'mistral-premium': 'mistral-medium-2505'
};

// --- Required field ---
const query = body.query || ctx.query;
if (!query || typeof query !== 'string' || query.trim().length === 0) {
  errors.push('query requis (chaine non vide)');
}

// --- Provider validation ---
const provider = body.provider || ctx.provider || 'gemini';
if (!validProviders.includes(provider)) {
  errors.push(`provider invalide: '${provider}'. Options valides: ${validProviders.join(', ')}`);
}

// --- API Keys validation based on provider ---
if (provider.startsWith('openai') && !body.openai_api_key) {
  errors.push('openai_api_key requis pour le provider OpenAI');
}
if ((provider.startsWith('claude') || provider === 'anthropic') && !body.anthropic_api_key) {
  errors.push('anthropic_api_key requis pour le provider Claude/Anthropic');
}
if (provider.startsWith('gemini') && !body.google_api_key) {
  errors.push('google_api_key requis pour le provider Gemini');
}
if (provider.startsWith('mistral') && !body.mistral_api_key) {
  errors.push('mistral_api_key requis pour le provider Mistral');
}

// --- OPTIONAL context fields for tracing (NO validation errors) ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- Options ---
const opts = body.options || ctx.options || {};

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

return {
  valid: true,
  query: (query || '').trim(),
  provider: provider,
  provider_type: provider === 'anthropic' ? 'claude' : provider.split('-')[0],
  model: body.model || ctx.model || defaultModels[provider],
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  openai_api_key: body.openai_api_key,
  anthropic_api_key: body.anthropic_api_key,
  google_api_key: body.google_api_key,
  mistral_api_key: body.mistral_api_key,
  options: {
    search_depth: opts.search_depth || 'medium',
    max_results: opts.max_results || 3,
    language: opts.language || 'fr',
    allowed_domains: opts.allowed_domains || [],
    blocked_domains: opts.blocked_domains || [],
    include_sources: opts.include_sources !== false
  },
  output_schema: body.output_schema || ctx.output_schema || null,
  allowed_context: body.allowed_context || ctx.allowed_context || null,
  messages: body.messages || ctx.messages || null,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'none',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

// ============================================
// NORMALIZE OPENAI - With _trace support
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();

const usage = {
  input_tokens: input.usage?.prompt_tokens || 0,
  output_tokens: input.usage?.completion_tokens || 0,
  total_tokens: input.usage?.total_tokens || 0
};

function getDomain(url) {
  if (!url) return '';
  const match = url.match(/^https?:\/\/([^\/]+)/);
  return match ? match[1] : '';
}

try {
  let textContent = '';
  const sources = [];
  let structuredData = null;

  // Extract text content
  const message = input.choices?.[0]?.message;

  if (message?.content) {
    textContent = message.content;
  }

  // Extract sources (annotations)
  const annotations = message?.annotations || [];
  for (const ann of annotations) {
    if (ann.type === 'url_citation') {
      sources.push({
        title: ann.title || 'Source',
        url: ann.url,
        domain: getDomain(ann.url)
      });
    }
  }

  // Extract structured data (tool_calls)
  const toolCalls = message?.tool_calls || [];
  if (toolCalls.length > 0) {
    const call = toolCalls[0];
    if (call.type === 'function') {
      structuredData = {
        tool_name: call.function.name,
        data: JSON.parse(call.function.arguments)
      };
    }
  }

  return [{
    json: {
      normalized: true,
      provider: prevData.provider,
      query: prevData.query,
      content: textContent,
      sources,
      structured_data: structuredData,
      search_performed: sources.length > 0,
      has_structured_output: structuredData !== null,
      usage,
      user_id: prevData.user_id,
      guild_id: prevData.guild_id,
      user_request: prevData.user_request,
      startTime: startTime,
      raw_response: input
    }
  }];
} catch (e) {
  return [{
    json: {
      normalized: false,
      provider: prevData.provider,
      error: e.message,
      user_id: prevData.user_id,
      guild_id: prevData.guild_id,
      user_request: prevData.user_request,
      startTime: startTime,
      raw_response: input
    }
  }];
}

// ============================================
// NORMALIZE CLAUDE - With _trace support
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();

const usage = {
  input_tokens: input.usage?.input_tokens || 0,
  output_tokens: input.usage?.output_tokens || 0,
  total_tokens: (input.usage?.input_tokens || 0) + (input.usage?.output_tokens || 0)
};

function getDomain(url) {
  if (!url) return '';
  const match = url.match(/^https?:\/\/([^\/]+)/);
  return match ? match[1] : '';
}

try {
  let textContent = '';
  const sources = [];
  let structuredData = null;

  for (const block of (input.content || [])) {
    // Extract text
    if (block.type === 'text') {
      textContent += block.text;
    }

    // Extract web sources
    if (block.type === 'web_search_tool_result') {
      for (const result of (block.content || [])) {
        if (result.type === 'web_search_result') {
          sources.push({
            title: result.title || 'Source',
            url: result.url,
            domain: getDomain(result.url)
          });
        }
      }
    }

    // Extract structured data (tool_use)
    if (block.type === 'tool_use' && block.name !== 'web_search') {
      structuredData = {
        tool_name: block.name,
        data: block.input
      };
    }
  }

  return [{
    json: {
      normalized: true,
      provider: prevData.provider,
      query: prevData.query,
      content: textContent,
      sources,
      structured_data: structuredData,
      search_performed: sources.length > 0,
      has_structured_output: structuredData !== null,
      usage,
      user_id: prevData.user_id,
      guild_id: prevData.guild_id,
      user_request: prevData.user_request,
      startTime: startTime,
      raw_response: input
    }
  }];
} catch (e) {
  return [{
    json: {
      normalized: false,
      provider: prevData.provider,
      error: e.message,
      user_id: prevData.user_id,
      guild_id: prevData.guild_id,
      user_request: prevData.user_request,
      startTime: startTime,
      raw_response: input
    }
  }];
}

// ============================================
// NORMALIZE GEMINI - With _trace support
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();

const usage = {
  input_tokens: input.usageMetadata?.promptTokenCount || 0,
  output_tokens: input.usageMetadata?.candidatesTokenCount || 0,
  total_tokens: input.usageMetadata?.totalTokenCount || 0
};

function getDomain(url) {
  if (!url) return '';
  const match = url.match(/^https?:\/\/([^\/]+)/);
  return match ? match[1] : '';
}

try {
  let textContent = '';
  const sources = [];
  let structuredData = null;

  const candidate = input.candidates?.[0];
  const parts = candidate?.content?.parts || [];

  for (const part of parts) {
    // Extract text
    if (part.text) {
      textContent += part.text;
    }

    // Extract structured data (functionCall)
    if (part.functionCall && part.functionCall.name !== 'google_search') {
      structuredData = {
        tool_name: part.functionCall.name,
        data: part.functionCall.args
      };
    }
  }

  // Extract sources (grounding metadata)
  const grounding = candidate?.groundingMetadata;
  const chunks = grounding?.groundingChunks || [];

  for (const chunk of chunks) {
    if (chunk.web) {
      sources.push({
        title: chunk.web.title || 'Source',
        url: chunk.web.uri,
        domain: getDomain(chunk.web.uri)
      });
    }
  }

  return [{
    json: {
      normalized: true,
      provider: prevData.provider,
      query: prevData.query,
      content: textContent,
      sources,
      structured_data: structuredData,
      search_performed: sources.length > 0,
      has_structured_output: structuredData !== null,
      usage,
      user_id: prevData.user_id,
      guild_id: prevData.guild_id,
      user_request: prevData.user_request,
      startTime: startTime,
      raw_response: input
    }
  }];
} catch (e) {
  return [{
    json: {
      normalized: false,
      provider: prevData.provider,
      error: e.message,
      user_id: prevData.user_id,
      guild_id: prevData.guild_id,
      user_request: prevData.user_request,
      startTime: startTime,
      raw_response: input
    }
  }];
}

// ============================================
// NORMALIZE MISTRAL - With _trace support
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();

const usage = {
  input_tokens: input.usage?.prompt_tokens || 0,
  output_tokens: input.usage?.completion_tokens || 0,
  total_tokens: input.usage?.total_tokens || 0
};

function getDomain(url) {
  if (!url) return '';
  const match = url.match(/^https?:\/\/([^\/]+)/);
  return match ? match[1] : '';
}

try {
  let textContent = '';
  const sources = [];
  let structuredData = null;

  const message = input.choices?.[0]?.message;

  // Extract text content
  if (message?.content) {
    textContent = message.content;
  }

  // Extract sources from citations
  const citations = input.citations || [];
  for (const cite of citations) {
    sources.push({
      title: cite.title || 'Source',
      url: cite.url,
      domain: getDomain(cite.url)
    });
  }

  // Extract structured data (tool_calls)
  const toolCalls = message?.tool_calls || [];
  for (const call of toolCalls) {
    if (call.type === 'function' && call.function.name !== 'web_search') {
      structuredData = {
        tool_name: call.function.name,
        data: JSON.parse(call.function.arguments)
      };
      break;
    }
  }

  return [{
    json: {
      normalized: true,
      provider: prevData.provider,
      query: prevData.query,
      content: textContent,
      sources,
      structured_data: structuredData,
      search_performed: sources.length > 0,
      has_structured_output: structuredData !== null,
      usage,
      user_id: prevData.user_id,
      guild_id: prevData.guild_id,
      user_request: prevData.user_request,
      startTime: startTime,
      raw_response: input
    }
  }];
} catch (e) {
  return [{
    json: {
      normalized: false,
      provider: prevData.provider,
      error: e.message,
      user_id: prevData.user_id,
      guild_id: prevData.guild_id,
      user_request: prevData.user_request,
      startTime: startTime,
      raw_response: input
    }
  }];
}

// ============================================
// FORMAT OUTPUT - With _trace (llm_response, service_response)
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = input.startTime || prevData.startTime || Date.now();

const userId = input.user_id || prevData.user_id;
const guildId = input.guild_id || prevData.guild_id;
const userRequest = input.user_request || prevData.user_request;
const rawResponse = input.raw_response || null;

try {
  if (!input.normalized) {
    return [{
      json: {
        success: false,
        error: {
          code: 'NORMALIZE_ERROR',
          message: input.error || 'Failed to normalize response',
          http_status: 500
        },
        user_id: userId,
        guild_id: guildId,
        user_request: userRequest,
        _trace: {
          llm_response: null,
          service_response: rawResponse,
          provider: input.provider || prevData.provider,
          model: prevData.model,
          tokens: input.usage || { input: 0, output: 0 },
          latency_ms: Date.now() - startTime,
          user_id: userId,
          guild_id: guildId,
          user_request: userRequest
        }
      }
    }];
  }

  // Build _trace object
  const _trace = {
    llm_response: input.content || null,
    service_response: rawResponse,
    provider: input.provider || prevData.provider,
    model: prevData.model,
    tokens: {
      input: input.usage?.input_tokens || 0,
      output: input.usage?.output_tokens || 0,
      total: input.usage?.total_tokens || 0
    },
    latency_ms: Date.now() - startTime,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };

  // If structured data (tool_use), return it directly
  if (input.structured_data) {
    return [{
      json: {
        success: true,
        data: input.structured_data.data,
        sources: input.sources || [],
        meta: {
          provider: input.provider || prevData.provider,
          model: prevData.model,
          tool_used: input.structured_data.tool_name,
          search_performed: input.search_performed,
          sources_count: (input.sources || []).length
        },
        usage: input.usage || null,
        user_id: userId,
        guild_id: guildId,
        user_request: userRequest,
        _trace: _trace
      }
    }];
  }

  // Otherwise, return classic text response
  return [{
    json: {
      success: true,
      data: {
        query: prevData.query,
        content: input.content,
        sources: input.sources || []
      },
      meta: {
        provider: input.provider || prevData.provider,
        model: prevData.model,
        search_performed: input.search_performed,
        sources_count: (input.sources || []).length
      },
      usage: input.usage || null,
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest,
      _trace: _trace
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: {
        code: 'FORMAT_ERROR',
        message: 'Failed to format output: ' + e.message,
        http_status: 500
      },
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest,
      _trace: {
        llm_response: null,
        service_response: rawResponse,
        provider: prevData.provider,
        model: prevData.model,
        tokens: input.usage || { input: 0, output: 0 },
        latency_ms: Date.now() - startTime,
        user_id: userId,
        guild_id: guildId,
        user_request: userRequest
      }
    }
  }];
}

// ============================================
// PREPARE CLAUDE BODY - With user_request injection
// ============================================

const data = $input.first().json;

const tools = [
  {
    type: "web_search_20250305",
    name: "web_search",
    max_uses: data.options.max_results || 5
  }
];

// If output schema provided, add it as tool
if (data.output_schema) {
  tools.push({
    name: data.output_schema.name || "structured_output",
    description: data.output_schema.description || "Return structured data",
    input_schema: data.output_schema.input_schema
  });
}

// Build the user message content
let userContent = data.query;

// Inject user_request context if available
if (data.user_request) {
  userContent = `User context: ${data.user_request}\n\nQuery: ${data.query}`;
}

// If schema provided, add instruction to use the tool
if (data.output_schema) {
  userContent += `\n\nIMPORTANT: Tu DOIS utiliser le tool "${data.output_schema.name || 'structured_output'}" pour retourner ta reponse de maniere structuree.`;
}

// Use messages if provided, otherwise create from built content
let messages = data.messages || [{ role: "user", content: userContent }];

const body = {
  model: data.model,
  max_tokens: 8192,
  tools: tools,
  messages: messages
};

return [{
  json: {
    ...data,
    claude_body: JSON.stringify(body)
  }
}];

// ============================================
// PREPARE OPENAI BODY - With user_request injection
// ============================================

const data = $input.first().json;

const tools = [];

// If output schema provided
if (data.output_schema) {
  tools.push({
    type: "function",
    function: {
      name: data.output_schema.name || "structured_output",
      description: data.output_schema.description || "Return structured data",
      parameters: data.output_schema.input_schema
    }
  });
}

// Build the user message content
let userContent = data.query;

// Inject user_request context if available
if (data.user_request) {
  userContent = `User context: ${data.user_request}\n\nQuery: ${data.query}`;
}

// If schema provided, add instruction to use the tool
if (data.output_schema) {
  userContent += `\n\nIMPORTANT: You MUST use the function "${data.output_schema.name || 'structured_output'}" to return your response in a structured format.`;
}

// Use messages if provided, otherwise create from built content
let messages = data.messages || [{ role: "user", content: userContent }];

const body = {
  model: data.model,
  max_tokens: 8192,
  messages: messages,
  web_search_options: {
    search_context_size: data.options.search_depth === 'deep' ? 'high' : 'medium'
  }
};

// Add tools only if present
if (tools.length > 0) {
  body.tools = tools;
  body.tool_choice = { type: "function", function: { name: data.output_schema.name } };
}

return [{
  json: {
    ...data,
    openai_body: JSON.stringify(body)
  }
}];

// ============================================
// PREPARE GEMINI BODY - With user_request injection
// ============================================

const data = $input.first().json;

const tools = [
  { google_search: {} }  // Grounding with Google Search
];

// If output schema provided
if (data.output_schema) {
  tools.push({
    function_declarations: [{
      name: data.output_schema.name || "structured_output",
      description: data.output_schema.description || "Return structured data",
      parameters: data.output_schema.input_schema
    }]
  });
}

// Build the user message content
let userContent = data.query;

// Inject user_request context if available
if (data.user_request) {
  userContent = `User context: ${data.user_request}\n\nQuery: ${data.query}`;
}

// If schema provided, add instruction to use the function
if (data.output_schema) {
  userContent += `\n\nIMPORTANT: You MUST use the function "${data.output_schema.name || 'structured_output'}" to return your response in a structured format.`;
}

// Convert messages to Gemini format (contents)
let contents;
if (data.messages && data.messages.length > 0) {
  contents = data.messages.map(m => ({
    role: m.role === 'assistant' ? 'model' : 'user',
    parts: [{ text: m.content }]
  }));
} else {
  contents = [{
    role: "user",
    parts: [{ text: userContent }]
  }];
}

const body = {
  contents: contents,
  tools: tools,
  generationConfig: {
    maxOutputTokens: 8192
  }
};

// Force tool usage if schema provided
if (data.output_schema) {
  body.tool_config = {
    function_calling_config: {
      mode: "ANY",
      allowed_function_names: [data.output_schema.name]
    }
  };
}

return [{
  json: {
    ...data,
    gemini_body: JSON.stringify(body)
  }
}];

// ============================================
// PREPARE MISTRAL BODY - With user_request injection
// ============================================

const data = $input.first().json;

const tools = [
  { type: "web_search" }  // Native Mistral web search
];

// If output schema provided
if (data.output_schema) {
  tools.push({
    type: "function",
    function: {
      name: data.output_schema.name || "structured_output",
      description: data.output_schema.description || "Return structured data",
      parameters: data.output_schema.input_schema
    }
  });
}

// Build the user message content
let userContent = data.query;

// Inject user_request context if available
if (data.user_request) {
  userContent = `User context: ${data.user_request}\n\nQuery: ${data.query}`;
}

// If schema provided, add instruction to use the function
if (data.output_schema) {
  userContent += `\n\nIMPORTANT: You MUST use the function "${data.output_schema.name || 'structured_output'}" to return your response in a structured format.`;
}

// Use messages if provided, otherwise create from built content
let messages = data.messages || [{ role: "user", content: userContent }];

const body = {
  model: data.model,
  max_tokens: 8192,
  messages: messages,
  tools: tools
};

// Force tool usage if schema provided
if (data.output_schema) {
  body.tool_choice = "any";
}

return [{
  json: {
    ...data,
    mistral_body: JSON.stringify(body)
  }
}];

// ============================================
// CHECK CONTEXT - Prepare context validation
// ============================================

const data = $input.first().json;

// If no context to check, pass through
if (!data.allowed_context) {
  return [{
    json: {
      ...data,
      context_check: {
        required: false,
        valid: true
      }
    }
  }];
}

const ctx = data.allowed_context;

// Build verification prompt (generic)
const checkPrompt = `Tu es un moderateur de contenu. Verifie si une requete correspond au contexte autorise.

CONTEXTE AUTORISE:
${ctx.description}

REQUETE:
"${data.query}"

REGLES:
- Reponds UNIQUEMENT par un JSON valide
- {"valid": true} si la requete est dans le contexte
- {"valid": false, "reason": "explication courte"} si hors contexte
- Sois strict mais juste

JSON:`;

// Use the provider's model from input
const llmBody = {
  model: data.model,
  max_tokens: 100,
  messages: [{
    role: "user",
    content: checkPrompt
  }]
};

return [{
  json: {
    ...data,
    context_check: {
      required: true,
      prompt: checkPrompt,
      llm_body: JSON.stringify(llmBody)
    }
  }
}];

// ============================================
// PARSE CONTEXT RESPONSE
// ============================================

const prevData = $('Check Context').first().json;
const llmResponse = $input.first().json;

// Check for LLM error or empty response
if (!llmResponse || llmResponse.error || !llmResponse.content) {
  // If LLM error, allow request (fail open)
  return [{
    json: {
      ...prevData,
      context_check: {
