  userContent = `User context: ${data.user_request}\n\nQuery: ${data.query}`;
}

// If schema provided, add instruction to use the function
if (data.output_schema) {
  userContent += `\n\nIMPORTANT: You MUST use the function "${data.output_schema.name || 'structured_output'}" to return your response in a structured format.`;
}

// Use messages if provided, otherwise create from built content
let messages = data.messages || [{ role: "user", content: userContent }];

const body = {
  model: data.model,
  max_tokens: 8192,
  messages: messages,
  tools: tools
};

// Force tool usage if schema provided
if (data.output_schema) {
  body.tool_choice = "any";
}

return [{
  json: {
    ...data,
    mistral_body: JSON.stringify(body)
  }
}];

// ============================================
// CHECK CONTEXT - Prepare context validation
// ============================================

const data = $input.first().json;

// If no context to check, pass through
if (!data.allowed_context) {
  return [{
    json: {
      ...data,
      context_check: {
        required: false,
        valid: true
      }
    }
  }];
}

const ctx = data.allowed_context;

// Build verification prompt (generic)
const checkPrompt = `Tu es un moderateur de contenu. Verifie si une requete correspond au contexte autorise.

CONTEXTE AUTORISE:
${ctx.description}

REQUETE:
"${data.query}"

REGLES:
- Reponds UNIQUEMENT par un JSON valide
- {"valid": true} si la requete est dans le contexte
- {"valid": false, "reason": "explication courte"} si hors contexte
- Sois strict mais juste

JSON:`;

// Use the provider's model from input
const llmBody = {
  model: data.model,
  max_tokens: 100,
  messages: [{
    role: "user",
    content: checkPrompt
  }]
};

return [{
  json: {
    ...data,
    context_check: {
      required: true,
      prompt: checkPrompt,
      llm_body: JSON.stringify(llmBody)
    }
  }
}];

// ============================================
// PARSE CONTEXT RESPONSE
// ============================================

const prevData = $('Check Context').first().json;
const llmResponse = $input.first().json;

// Check for LLM error or empty response
if (!llmResponse || llmResponse.error || !llmResponse.content) {
  // If LLM error, allow request (fail open)
  return [{
    json: {
      ...prevData,
      context_check: {
        ...prevData.context_check,
        valid: true,
        error: llmResponse?.error?.message || 'LLM check failed, allowing request'
      }
    }
  }];
}

try {
  // Extract text from Claude response
  const responseText = llmResponse.content?.[0]?.text || '';

  // Parse JSON from response
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);

  if (!jsonMatch) {
    // If no valid JSON, consider valid by default
    return [{
      json: {
        ...prevData,
        context_check: {
          ...prevData.context_check,
          valid: true,
          raw_response: responseText
        }
      }
    }];
  }

  const parsed = JSON.parse(jsonMatch[0]);

  return [{
    json: {
      ...prevData,
      context_check: {
        ...prevData.context_check,
        valid: parsed.valid === true,
        reason: parsed.reason || null,
        raw_response: responseText
      }
    }
  }];

} catch (e) {
  // On parsing error, allow request (fail open)
  return [{
    json: {
      ...prevData,
      context_check: {
        ...prevData.context_check,
        valid: true,
        error: e.message
      }
    }
  }];
}

// ============================================
// CONTEXT ERROR RESPONSE - With _trace
// ============================================

const data = $input.first().json;
const ctx = data.allowed_context;

return [{
  json: {
    success: false,
    error: {
      code: 'CONTEXT_VIOLATION',
      message: data.context_check.reason || 'Cette requete ne correspond pas au contexte autorise',
      http_status: 403,
      details: {
        query: data.query,
        allowed_context: ctx.description,
        suggestion: ctx.suggestion || `Ce bot est dedie a: ${ctx.description}`
      }
    },
    user_id: data.user_id,
    guild_id: data.guild_id,
    user_request: data.user_request,
    _trace: {
      llm_response: null,
      service_response: { context_check: data.context_check },
      provider: data.provider,
      model: data.model,
      tokens: { input: 0, output: 0 },
      latency_ms: Date.now() - (data.startTime || Date.now()),
      user_id: data.user_id,
      guild_id: data.guild_id,
      user_request: data.user_request
    }
  }
}];
